    pub fn first_token_after_comment_and_metadata(&self, ast: &AstStore, tokens: &TokenStore) -> TokenId {
        if self.augment_keyword != NO_TOKEN {
            return self.augment_keyword;
        }
        {
            let result = tokens.lexically_first(&[self.external_keyword, self.static_keyword]);
            if result != NO_TOKEN {
                return result;
            }
        }
        if self.return_type != NO_NODE {
            return ast.begin_token(self.return_type, tokens);
        }
        return self.set_keyword;
    }

