impl AstStore {
    /// `FormalParameterListImpl.allFormalParameters`: the required positional
    /// parameters, then the delimited ones.
    pub fn all_formal_parameters(&self, formal_parameter_list: NodeId) -> Vec<NodeId> {
        let list = self.node(formal_parameter_list).as_formal_parameter_list_impl();
        let mut result = list.required_positional_formal_parameters.clone();
        if list.delimited_formal_parameters != NO_NODE {
            result.extend_from_slice(
                &self
                    .node(list.delimited_formal_parameters)
                    .as_delimited_formal_parameters_impl()
                    .formal_parameters,
            );
        }
        result
    }

    /// `FormalParameterImpl.kind` (as the subclasses store it).
    pub fn formal_parameter_kind(&self, parameter: NodeId) -> ParameterKind {
        match self.node(parameter) {
            AstNodeImpl::RegularFormalParameterImpl(p) => p.kind,
            AstNodeImpl::FieldFormalParameterImpl(p) => p.kind,
            AstNodeImpl::SuperFormalParameterImpl(p) => p.kind,
            other => panic!("{} is not a FormalParameterImpl", other.runtime_type()),
        }
    }

    /// `ParsedValueArgumentsImpl.dotShorthandInvocationParts`: the head and
    /// the type arguments, or null.
    pub fn dot_shorthand_invocation_parts(&self, node: NodeId) -> Option<(NodeId, NodeId)> {
        let operand = self.node(node).as_parsed_value_arguments_impl().operand;
        match self.node(operand) {
            AstNodeImpl::ParsedDotShorthandNameImpl(_) => Some((operand, NO_NODE)),
            AstNodeImpl::ParsedTypeArgumentsImpl(t)
                if matches!(self.node(t.operand), AstNodeImpl::ParsedDotShorthandNameImpl(_)) =>
            {
                Some((t.operand, t.type_arguments))
            }
            _ => None,
        }
    }

    /// `ParsedValueArgumentsImpl.namedInvocationParts`: the selector and the
    /// type arguments, or null.
    pub fn named_invocation_parts(&self, node: NodeId) -> Option<(NodeId, NodeId)> {
        let operand = self.node(node).as_parsed_value_arguments_impl().operand;
        match self.node(operand) {
            AstNodeImpl::ParsedNameAccessImpl(_) => Some((operand, NO_NODE)),
            AstNodeImpl::ParsedTypeArgumentsImpl(t)
                if matches!(self.node(t.operand), AstNodeImpl::ParsedNameAccessImpl(_)) =>
            {
                Some((t.operand, t.type_arguments))
            }
            _ => None,
        }
    }
}
